args.sql:
-- Check distinct onlineuse and mobileuse values
SELECT DISTINCT chaninvdatablock->>'onlineuse' as online, 
       chaninvdatablock->>'mobileuse' as mobile FROM bank_and_transactions LIMIT 10;

-- Check distinct cohort quarters
SELECT DISTINCT EXTRACT(QUARTER FROM (cr.scoredate::date - (cr.tenureyrs || ' years')::interval)) as cohort_qtr
FROM core_record cr ORDER BY 1;

-- Check if EXTRACT returns numeric vs integer
SELECT typeof(EXTRACT(YEAR FROM (cr.scoredate::date - (cr.tenureyrs || ' years')::interval)) as year_type
FROM core_record cr LIMIT 1;
